media_queries:
@media print {
    body {
        width: auto;
        min-height: auto;
        margin: 0;
    }

    /* 避免孤行寡行 */
    h1, h2, h3, h4, h5, h6 {
        page-break-after: avoid;
    }

    p, li, blockquote {
        page-break-inside: avoid;
    }

    /* 确保表格不跨页断开 */
    table {
        page-break-inside: avoid;
    }

    /* 插图和特殊容器不跨页 */
    .thought-theater,
    .think-about,
    .ancient-saying,
    .global-telescope,
    .wisdom-map,
    .philosophy-vocab,
    .illustration-container {
        page-break-inside: avoid;
    }
}

@media screen and (max-width: 600px) {
    body {
        width: 100%;
        min-height: auto;
        margin: 0;
        padding: 15px;
        font-size: 16px; /* 稍大字号，便于手机阅读 */
    }

    .book-content {
        width: 100%;
        max-width: 100%;
        margin: 0 auto;
    }

    h1 {
        font-size: 28px;
        margin: 1.5em 0 1em 0;
    }

    h2 {
        font-size: 22px;
        margin: 1.2em 0 0.8em 0;
    }

    h3 {
        font-size: 18px;
        margin: 1em 0 0.6em 0;
    }

    p {
        font-size: 17px;
        line-height: 1.6;
        margin-bottom: 1.2em;
    }

    /* 特殊容器在移动端调整内边距 */
    .thought-theater,
    .think-about,
    .ancient-saying,
    .global-telescope,
    .wisdom-map,
    .philosophy-vocab {
        padding: 1em;
        margin: 1.2em 0;
    }

    /* 表格在移动端变为滚动 */
    .global-telescope .comparison-table,
    .philosophy-vocab table {
        display: block;
        overflow-x: auto;
        white-space: nowrap;
    }

    /* 确保图片完全响应 */
    .chapter-illustration {
        max-width: 100% !important;
        height: auto !important;
    }

    .illustration-container {
        margin: 1em 0;
    }
}

@media screen and (max-width: 400px) {
    body {
        font-size: 15px;
        padding: 10px;
    }

    h1 {
        font-size: 24px;
    }

    h2 {
        font-size: 20px;
    }

    .thought-theater,
    .think-about,
    .ancient-saying,
    .global-telescope,
    .wisdom-map,
    .philosophy-vocab {
        padding: 0.8em;
    }
}

